<?php require __DIR__.'/../helpers/paymongo.php';$u=lender_user();$rows=lender_rows('SELECT o.*,u.user_fn,u.user_ln FROM paymongo_orders o JOIN users u ON u.user_id=o.borrower_id WHERE o.lender_id=? ORDER BY o.created_at DESC',[$u['user_id']]);?><!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Online payments</title><link rel="stylesheet" href="../assets/css/borrower-portal.css"><?php uw_role_design_assets('lender', basename(__FILE__, '.php')); ?><link rel="stylesheet" href="../assets/css/integ-lender/lender-live.css"></head><body><div class="admin-layout"><?php $lenderAccount=$u; require __DIR__.'/../helpers/lender_sidebar.php'; ?><main class="main-content"><?php require __DIR__.'/../helpers/lender_topbar.php'; ?><div class="live-body"><a href="dashboard.php">Back to dashboard</a><h1>Online payments</h1><?php notice(); ?><p>Received payments needing reconciliation are not deducted again automatically. Check your PayMongo account and contact the borrower before resolving a changed schedule or refund.</p><?php foreach($rows as $o): ?><section class="portal-card"><h2><?= e($o['user_fn'].' '.$o['user_ln']) ?> · UW-<?= $o['agreement_id'] ?></h2><p>Reference: <?= e($o['order_id']) ?></p><p><?= money($o['amount_cents']/100) ?> · <?= e($o['mode']) ?> · <?= e($o['state']) ?><?= !$o['livemode']?' (test)':'' ?></p><p><?= e($o['error_note']) ?></p><?php if($o['state']!=='paid'): ?><form class="portal-form" method="post" action="../controllers/lender-online-payment.php"><?php csrf(); ?><input type="hidden" name="order_id" value="<?= e($o['order_id']) ?>"><?php if(!$o['session_id']): ?><label>PayMongo checkout session ID (from your provider dashboard)<input name="session_id" pattern="cs_[a-zA-Z0-9]+" required></label><?php endif; ?><button name="action" value="check">Check with PayMongo</button><?php if($o['session_id']&&in_array($o['state'],['pending','uncertain'],true)): ?><button name="action" value="expire">Close unpaid checkout</button><?php endif; ?></form><?php endif; ?></section><?php endforeach; if(!$rows): ?><p>No online payments yet.</p><?php endif; ?></div></main></div><?php uw_success_assets(); ?><script src="../assets/js/lender-notifications.js" defer></script></body></html>